<template><div class="admin-availability-page"><header class="applications-page-header"><div><h1>Availability</h1><p>Generic booking types, eligible staff, schedules, unavailability, coverage, and capacity.</p></div><span class="demo-data-badge">Demo data</span></header><nav class="availability-tabs" aria-label="Availability sections"><a v-for="x in sections" :key="x.id" :href="`#${x.id}`">{{x.label}}</a></nav><section id="overview" class="application-panel"><h2>Overview</h2><div class="application-summary-grid"><article><strong>{{activeCount}}</strong><span>Active booking types</span></article><article><strong>{{draftCount}}</strong><span>Draft booking types</span></article><article><strong>{{profiles.filter(x=>x.active).length}}</strong><span>Active eligible staff</span></article></div></section><section id="booking-types" class="application-panel"><div class="panel-heading"><h2>Booking types</h2><button v-if="isAdmin" @click="startCreate">Create booking type</button></div><div class="booking-admin-grid"><article v-for="type in types" :key="type.id"><h3>{{type.name}}</h3><p>{{type.shortDescription}}</p><small>{{type.status}} · {{type.accessType}} · {{type.duration}} minutes · {{type.eligibleStaffIds.length}} eligible staff</small><div v-if="isAdmin"><button @click="edit(type)">Edit</button><button @click="toggle(type)">{{type.status==='active'?'Deactivate':'Activate'}}</button><RouterLink :to="{name:'BookingsType',params:{bookingTypeSlug:type.slug}}">Preview</RouterLink></div></article></div></section><form v-if="editing&&isAdmin" class="application-panel booking-type-form" @submit.prevent="save"><h2>{{form.id?'Edit':'Create'}} booking type</h2><label>Name<input v-model="form.name"/></label><label>Slug<input v-model="form.slug"/></label><label>Status<select v-model="form.status"><option>draft</option><option>active</option><option>inactive</option></select></label><label>Access<select v-model="form.accessType"><option>public</option><option>account-required</option><option>invitation-only</option><option>internal</option></select></label><label>Audience<input v-model="form.audience"/></label><label>Duration<input v-model.number="form.duration" type="number"/></label><label>Buffer before<input v-model.number="form.bufferBefore" type="number"/></label><label>Buffer after<input v-model.number="form.bufferAfter" type="number"/></label><label>Minimum notice hours<input v-model.number="form.minimumNoticeHours" type="number"/></label><label>Booking horizon days<input v-model.number="form.bookingHorizonDays" type="number"/></label><fieldset><legend>Eligible staff</legend><label v-for="staff in profiles" :key="staff.id"><input v-model="form.eligibleStaffIds" type="checkbox" :value="staff.id"/>{{staff.name}}</label></fieldset><label>Public instructions<textarea v-model="form.instructions"></textarea></label><label>Confirmation message<textarea v-model="form.confirmationMessage"></textarea></label><label><input v-model="form.publicVisibility" type="checkbox"/> Public visibility</label><p v-if="error" role="alert">{{error}}</p><button>Save booking type</button><button type="button" @click="editing=false">Cancel</button></form><section id="staff-schedules"><h2 class="sr-only">Staff schedules, unavailability and calendar</h2><div class="generic-availability-embed"><AdminInductionAvailability/></div></section><span id="unavailability" class="anchor-target"></span><span id="calendar" class="anchor-target"></span></div></template>
<script>import AdminInductionAvailability from'../AdminApplications/AdminInductionAvailability.vue';import{demoWorkflow,getDemoIdentity}from'../AdminApplications/applicationAdminData.js';import{DEMO_STAFF_PROFILES,getBookingType,listBookingTypes,saveBookingType,setBookingTypeStatus}from'./bookingAvailabilityData.js';const blank=()=>({name:'',slug:'',shortDescription:'',instructions:'',status:'draft',accessType:'public',audience:'General',accountRequired:false,invitationRequired:false,duration:30,bufferBefore:10,bufferAfter:10,minimumNoticeHours:24,bookingHorizonDays:30,cancellationPolicy:'',eligibleStaffIds:[],displayOrder:99,publicVisibility:false,confirmationMessage:'',preparationInstructions:''});export default{name:'AdminAvailability',components:{AdminInductionAvailability},data:()=>({workflow:demoWorkflow,profiles:DEMO_STAFF_PROFILES,editing:false,error:'',form:blank(),sections:[{id:'overview',label:'Overview'},{id:'booking-types',label:'Booking types'},{id:'staff-schedules',label:'Staff schedules'},{id:'unavailability',label:'Unavailability'},{id:'calendar',label:'Calendar'}]}),computed:{identity(){this.workflow.revision;return getDemoIdentity()},isAdmin(){return this.identity.role==='admin'},types(){return listBookingTypes({includeUnpublished:true})},activeCount(){return this.types.filter(x=>x.status==='active').length},draftCount(){return this.types.filter(x=>x.status==='draft').length}},methods:{startCreate(){this.form=blank();this.editing=true},edit(type){this.form=JSON.parse(JSON.stringify(type));this.editing=true},save(){this.error='';try{saveBookingType(this.form);this.editing=false}catch(e){this.error=e.message}},toggle(type){this.error='';try{setBookingTypeStatus(type.id,type.status==='active'?'inactive':'active')}catch(e){this.error=e.message}}}};</script><style src="../AdminApplications/AdminApplications.css"></style>
